//! Upgrading a v1.0.3 profile (schema 124) with the current code (audit
//! 2026-11-11, R5).
//!
//! Every other test starts from a fresh schema, so migrations 125-130 had never
//! run against a database v1.0.3 actually wrote: they would first run on users'
//! data. The fixture `fixtures/v1_0_3_schema.sql` is byte-for-byte the
//! `src-tauri/contract/app-schema.sql` of the v1.0.3 tag (git blob
//! 09700b0b59ef45bf10aa93183cf92672cf07e9bc): the DDL a v1.0.3 install holds
//! once every startup initialiser has run, generated by that release's own
//! migrations. On top of it go the rows a real v1.0.3 profile carries:
//! dependencies, advisories and their sync status, saved items, embeddings in
//! the BLOB column (pre-Phase 126), interest sources, learned preferences with
//! self-referential evidence (pre-Phase 125) and key-value settings.
//!
//! The test then opens the file exactly as the app does (`Database::new` plus
//! the startup initialisers) and checks that the data survives, each migration
//! did what it promises, and the two things a user reads first come out right:
//! advisory readiness and the Upgrade Plan.

use rusqlite::{params, Connection};

use super::Database;
use crate::osv::readiness::{advisory_sync, AdvisorySyncState};
use crate::test_utils::seed_embedding;

const V1_0_3_SCHEMA: &str = include_str!("fixtures/v1_0_3_schema.sql");

/// Rows a v1.0.3 profile holds, written against the v1.0.3 schema.
fn seed_v1_0_3_rows(c: &Connection) {
    c.execute_batch(
        "
        -- Dependencies from a lockfile walk: one npm and one Rust project.
        INSERT INTO user_dependencies (project_path, package_name, version, ecosystem, is_dev, is_direct, detected_from)
        VALUES ('/home/dev/web', 'lodash', '4.17.20', 'npm', 0, 1, 'lockfile'),
               ('/home/dev/web', 'react', '18.3.1', 'npm', 0, 1, 'lockfile'),
               ('/home/dev/svc', 'tokio', '1.38.0', 'rust', 0, 1, 'lockfile');

        -- The advisory mirror, synced an hour before the upgrade.
        INSERT INTO osv_advisories (advisory_id, summary, package_name, ecosystem, affected_ranges,
                                    fixed_versions, severity_type, cvss_score, source_url, published_at, aliases)
        VALUES ('GHSA-35jh-r3h4-6jhm', 'Command Injection in lodash', 'lodash', 'npm',
                '[{\"type\":\"SEMVER\",\"events\":[{\"introduced\":\"0\"},{\"fixed\":\"4.17.21\"}]}]',
                '[\"4.17.21\"]', 'CVSS_V3', 7.2, 'https://osv.dev/GHSA-35jh-r3h4-6jhm',
                '2021-05-06T16:05:51Z', '[\"CVE-2021-23337\"]'),
               ('RUSTSEC-2025-0023', 'Broadcast channel calls clone in parallel', 'tokio', 'crates.io',
                '[{\"type\":\"SEMVER\",\"events\":[{\"introduced\":\"0\"},{\"fixed\":\"1.38.2\"}]}]',
                '[\"1.38.2\"]', 'CVSS_V3', 5.5, 'https://osv.dev/RUSTSEC-2025-0023',
                '2025-04-07T00:00:00Z', '[\"GHSA-rr8g-9fpq-6wmg\"]');
        INSERT INTO osv_sync_status (ecosystem, last_synced_at, advisory_count, error)
        VALUES ('npm', datetime('now', '-1 hours'), 1, NULL),
               ('crates.io', datetime('now', '-1 hours'), 1, NULL);

        -- Sources: an advisory feed and an interest (news) feed, both on.
        INSERT INTO sources (source_type, name, enabled) VALUES ('osv', 'OSV.dev', 1),
                                                                ('hackernews', 'Hacker News', 1);

        -- Learned preferences: one facet backed by the user's save plus 4DA's
        -- own surfaced item, one backed only by what 4DA surfaced.
        INSERT INTO learned_facets (facet_id, class, key, value, stability, state, user_state,
                                    evidence_count, first_seen_at, last_seen_at)
        VALUES ('f-rust', 'topic_affinity', 'rust', 'surfaced', 0.4, 'candidate', 'auto', 2, 1790000000, 1790000100),
               ('f-java', 'topic_affinity', 'java', 'surfaced', 0.2, 'candidate', 'auto', 1, 1790000000, 1790000000);
        INSERT INTO facet_evidence (facet_id, cue_family, evidence_type, confidence, observed_at)
        VALUES ('f-rust', 'engagement', 'save', 0.9, 1790000000),
               ('f-rust', 'surface', 'analysis_surface', 0.3, 1790000100),
               ('f-java', 'surface', 'analysis_surface', 0.3, 1790000000);

        -- Settings kept in the database.
        INSERT INTO kv_store (key, value) VALUES ('onboarding_completed_at', '2026-10-06T09:00:00Z');
        INSERT INTO app_meta (key, value) VALUES ('install_id_created', '2026-10-06');
        ",
    )
    .expect("seed v1.0.3 rows");

    // Two items with their embedding in the BLOB column (v1.0.3 wrote it
    // there; Phase 126 moves it to source_vec), the first one saved.
    for (i, title) in ["Tokio 1.38.2 released", "Lodash advisory explained"]
        .iter()
        .enumerate()
    {
        let blob: Vec<u8> = seed_embedding(title)
            .iter()
            .flat_map(|f| f.to_le_bytes())
            .collect();
        c.execute(
            "INSERT INTO source_items (source_type, source_id, url, title, content, content_hash, embedding)
             VALUES ('hackernews', ?1, ?2, ?3, '', ?4, ?5)",
            params![
                format!("hn-{i}"),
                format!("https://news.example/{i}"),
                title,
                format!("hash-{i}"),
                blob
            ],
        )
        .expect("seed item");
    }
    c.execute(
        "INSERT INTO interactions (item_id, action_type, signal_strength)
         SELECT id, 'save', 1.0 FROM source_items WHERE source_id = 'hn-0'",
        [],
    )
    .expect("save");
}

/// A schema-124 database file as v1.0.3 leaves it.
fn v1_0_3_profile(dir: &std::path::Path) -> std::path::PathBuf {
    crate::register_sqlite_vec_extension();
    let path = dir.join("4da.db");
    let mut c = Connection::open(&path).expect("open");
    // One transaction: committing each of ~470 statements separately costs
    // ~30 s of fsyncs on a busy disk.
    let tx = c.transaction().expect("begin");
    tx.execute_batch(V1_0_3_SCHEMA)
        .expect("v1.0.3 schema loads");
    let version: i64 = tx
        .query_row("SELECT MAX(version) FROM schema_version", [], |r| r.get(0))
        .expect("version");
    assert_eq!(version, 124, "the fixture is v1.0.3's schema");
    seed_v1_0_3_rows(&tx);
    tx.commit().expect("commit");
    path
}

/// Open the profile the way the app's startup does.
fn open_like_the_app(path: &std::path::Path) -> Database {
    let db = Database::new(path).expect("current code opens and migrates a v1.0.3 profile");
    crate::ace::db::migrate(&db.conn).expect("ACE schema");
    crate::context_engine::ContextEngine::new(db.conn.clone()).expect("context-engine schema");
    crate::engine_runs::ensure_table(&db.conn.lock()).expect("engine_runs schema");
    db
}

fn count(db: &Database, sql: &str) -> i64 {
    db.conn
        .lock()
        .query_row(sql, [], |r| r.get(0))
        .unwrap_or_else(|e| panic!("{sql}: {e}"))
}

#[test]
fn a_v1_0_3_profile_upgrades_with_its_data_and_reads_correctly() {
    let dir = tempfile::tempdir().expect("temp dir");
    let path = v1_0_3_profile(dir.path());
    let db = open_like_the_app(&path);

    // Schema: at the version a fresh install reaches.
    let fresh = crate::test_utils::test_db();
    assert_eq!(
        count(&db, "SELECT MAX(version) FROM schema_version"),
        count(&fresh, "SELECT MAX(version) FROM schema_version"),
        "the v1.0.3 profile reaches the current schema"
    );

    // Dependencies and advisories survive, with the new columns defaulted.
    assert_eq!(count(&db, "SELECT COUNT(*) FROM user_dependencies"), 3);
    assert_eq!(count(&db, "SELECT COUNT(*) FROM osv_advisories"), 2);
    assert_eq!(
        count(
            &db,
            "SELECT COUNT(*) FROM osv_advisories WHERE cwe_ids IS NULL AND informational = 0"
        ),
        2,
        "Phases 128-129 add their columns; rows fill on the next sync"
    );

    // Phases 128-130 make every ecosystem's sync due, without erasing when
    // the data was last verified, and readiness still reads Ready: the data
    // is hours old, well inside the trust horizon, not "never synced".
    assert_eq!(
        count(
            &db,
            "SELECT COUNT(*) FROM osv_sync_status
              WHERE last_synced_at <= datetime('now', '-5 hours') AND error IS NULL"
        ),
        2,
        "every advisory ecosystem is due for a re-sync"
    );
    let readiness = advisory_sync(&db);
    assert_eq!(readiness.state, AdvisorySyncState::Ready, "{readiness:?}");
    assert_eq!(readiness.ecosystems, 2);
    assert!(readiness.synced_at.is_some(), "{readiness:?}");

    // The Upgrade Plan reads the migrated rows: both vulnerable dependencies,
    // each with the version that clears its advisory; react is not in it.
    let plan = crate::evidence::build_upgrade_plan(&db).expect("the plan reads the database");
    assert_eq!(plan.drops, 0);
    let mut targets: Vec<(String, Option<String>)> = plan
        .steps
        .iter()
        .flat_map(|s| {
            s.lines
                .iter()
                .map(move |l| (s.package.clone(), l.target.clone()))
        })
        .collect();
    targets.sort();
    assert_eq!(
        targets,
        vec![
            ("lodash".to_string(), Some("4.17.21".to_string())),
            ("tokio".to_string(), Some("1.38.2".to_string())),
        ],
        "plan steps: {:?}",
        plan.items.iter().map(|i| &i.title).collect::<Vec<_>>()
    );

    // Saved items survive, by the query the Saved list runs.
    let saved: Vec<String> = {
        let conn = db.conn.lock();
        let mut stmt = conn
            .prepare(
                "SELECT si.title FROM interactions i
                   JOIN source_items si ON si.id = i.item_id
                  WHERE i.action_type = 'save'",
            )
            .expect("saved query");
        let rows = stmt
            .query_map([], |r| r.get::<_, String>(0))
            .expect("saved rows")
            .collect::<rusqlite::Result<Vec<_>>>()
            .expect("saved titles");
        rows
    };
    assert_eq!(saved, vec!["Tokio 1.38.2 released".to_string()]);

    // Phase 126: embeddings move from the BLOB into source_vec (one copy),
    // and interests are turned off while the advisory feed stays on.
    assert_eq!(count(&db, "SELECT COUNT(*) FROM source_items"), 2);
    assert_eq!(count(&db, "SELECT COUNT(*) FROM source_vec"), 2);
    assert_eq!(
        count(
            &db,
            "SELECT COUNT(*) FROM source_items WHERE length(embedding) > 0"
        ),
        0
    );
    assert_eq!(
        count(
            &db,
            "SELECT enabled FROM sources WHERE source_type = 'hackernews'"
        ),
        0
    );
    assert_eq!(
        count(&db, "SELECT enabled FROM sources WHERE source_type = 'osv'"),
        1
    );

    // Phase 125: 4DA's own surfaced items no longer count as the user's taste.
    assert_eq!(
        count(
            &db,
            "SELECT COUNT(*) FROM facet_evidence WHERE evidence_type = 'analysis_surface'"
        ),
        0
    );
    assert_eq!(
        count(
            &db,
            "SELECT COUNT(*) FROM learned_facets WHERE facet_id = 'f-java'"
        ),
        0
    );
    assert_eq!(
        count(
            &db,
            "SELECT COUNT(*) FROM learned_facets
              WHERE facet_id = 'f-rust' AND evidence_count = 1 AND value = 'saved'"
        ),
        1
    );

    // Settings kept in the database survive.
    assert_eq!(
        count(
            &db,
            "SELECT COUNT(*) FROM kv_store WHERE key = 'onboarding_completed_at'"
        ),
        1
    );
    assert_eq!(count(&db, "SELECT COUNT(*) FROM app_meta"), 1);

    // A second start on the upgraded file is a no-op, not a second migration.
    drop(db);
    let again = open_like_the_app(&path);
    assert_eq!(count(&again, "SELECT COUNT(*) FROM user_dependencies"), 3);
    assert_eq!(count(&again, "SELECT COUNT(*) FROM source_vec"), 2);
}
